from pathlib import Path
import collections,csv,hashlib,json
R=Path('/Users/lanxingcan/Workspace/zstdoxize');D=R/'tests/fixtures/reference-admission-v2'
def read(p):return list(csv.DictReader(p.read_text().splitlines(),delimiter='\t'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
preset={(int(r['tier']),int(r['row'])):[int(r[k]) for k in ('window_log','chain_log','hash_log','search_log','min_match','target_length','strategy')] for r in read(R/'tests/upstream/parameters/presets.tsv')}
def adjust(p,size):
 p=p[:];w=min(p[0],max(6,(size-1).bit_length() if size else 6));p[1]=min(p[1],w+(p[6]>=6));p[2]=min(p[2],w+1);p[0]=max(10,w);return p
def classify(p):
 w,c,h,s,m,t,strategy=p
 if strategy not in (1,2,3):return 'unsupported'
 if w>({1:20,2:21,3:21}[strategy]) or h>(19 if strategy==3 else 18):return 'resource'
 if strategy==2 and c>18:return 'resource'
 if strategy==3 and w<=14 and (c>18 or s>8):return 'resource'
 return 'success'
result={'scope':'Source-only proposed Greedy admission forecast; no Rust Greedy codec or new C execution. v2 fixtures unchanged. These are planning expectations, not a published v3 fixture.','source_sha256':{str(p.relative_to(R)):sha(p) for p in [R/'tests/upstream/parameters/presets.tsv',D/'fuzz.tsv',D/'interop.tsv',D/'loops.tsv']}}
for name in ('fuzz','interop','loops'):
 rows=[]
 for r in read(D/(name+'.tsv')):
  if r['successor']=='advanced':p=None;status='advanced'
  else:
   p=list(map(int,r['historical_resolved_tuple'].split(','))) if name=='interop' else adjust(preset[int(r['preset_tier']),int(r['preset_row'])],int(r['prefix_size'] if name=='fuzz' else r['source_size']))
   status=classify(p)
  rows.append(dict(case=r.get('case',r.get('family','')+':'+r['level']),before=r['successor'],after=status,parameters=p))
 result[name]=dict(counts=dict(collections.Counter(r['after'] for r in rows)),changes=[r for r in rows if r['before']!=r['after']])
 if name=='loops':result[name]['families']={family:dict(collections.Counter(r['after'] for r in rows if r['case'].startswith(family+':'))) for family in ('empty','initial_match')}
Path('/tmp/zstdoxide-reference-greedy-forecast.json').write_text(json.dumps(result,sort_keys=True,indent=2)+'\n');print(json.dumps(result,indent=2))
